{"task_id": "T25", "code": "def solve(matrix):
    """Return the determinant of a square integer matrix.
    Uses the Bareiss algorithm to keep intermediate results integer.
    """
    if not matrix:
        return 1  # determinant of 0x0 matrix is conventionally 1
    n = len(matrix)
    # make a copy to avoid mutating input
    a = [list(row) for row in matrix]
    det = 1
    for k in range(n - 1):
        # Find pivot if zero
        if a[k][k] == 0:
            # swap with a lower row that has non-zero in column k
            swap_row = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            a[k], a[swap_row] = a[swap_row], a[k]
            det = -det
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss formula
                a[i][j] = (a[i][j] * a[k][k] - a[i][k] * a[k][j]) // (a[k - 1][k - 1] if k > 0 else 1)
        # Zero out column below pivot
        for i in range(k + 1, n):
            a[i][k] = 0
    return det * a[n - 1][n - 1]
"}

