    """Return the maximum number of non-overlapping meetings.
    Each meeting is a two-element iterable [start, end] (or tuple).
    Meetings where start > end are ignored.
    A meeting may start exactly when another ends.
    """
    # Filter out invalid meetings
    valid = []
    for m in meetings:
        try:
            start, end = m[0], m[1]
        except Exception:
            continue
        if start <= end:
            valid.append((start, end))
    if not valid:
        return 0
    # Sort by end time, then start time for determinism
    valid.sort(key=lambda x: (x[1], x[0]))
    count = 0
