{"task_id": "T30", "code": "def solve(path: str) -> str:
    """Simplify a Unix-style absolute path.
    The algorithm splits the path on '/', processes each component using a stack:
    - '' or '.' are ignored.
    - '..' pops the stack if possible (moving up one directory).
    - any other component is a valid directory name and is pushed.
    The resulting canonical path is '/' + '/'.join(stack). If the stack is empty, the result is '/'.
    """
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'"}

