def solve(coins, amount):
    # DP for min coins, unbounded.
    # dp[x] = min coins to make x, or inf if not possible.
    if amount < 0:
        return -1
    INF = amount + 1  # larger than any possible count
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= a:
                cand = dp[a - c] + 1
                if cand < best:
                    best = cand
        dp[a] = best
    return dp[amount] if dp[amount] != INF else -1

