    """Return the minimum number of coins needed to make *amount* using unlimited
    supply of each coin in *coins*. Return -1 if impossible.
    Uses classic unbounded knapsack DP.
    """
    if amount < 0:
        return -1
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= a:
