    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == n - 1:
            break
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
