def solve(grid):
    """Return the number of islands (connected components of 1s) in a binary grid.
    Uses DFS/BFS with O(m*n) time and O(m*n) extra space for visited.
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            x, y = stack.pop()
            for dr, dc in ((1,0), (-1,0), (0,1), (0,-1)):
                nr, nc = x + dr, y + dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == 1:
                    visited[nr][nc] = True
                    stack.append((nr, nc))
    islands = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                islands += 1
    return islands

