def solve(tokens):
    """Evaluate Reverse Polish Notation.
    Tokens may be strings or integers representing numbers, and the operators '+', '-', '*', '/'.
    Division truncates toward zero.
    """
    def trunc_div(a, b):
        # Truncate toward zero without using float.
        if b == 0:
            raise ZeroDivisionError('division by zero')
        q = abs(a) // abs(b)
        return q if (a * b) >= 0 else -q

    stack = []
    for t in tokens:
        # Ensure token is a string for operator check
        token = str(t)
        if token in ('+', '-', '*', '/') and len(token) == 1:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # '/'
                stack.append(trunc_div(a, b))
        else:
            # Operand: convert to int (handles int or numeric string)
            stack.append(int(t))
