    """Evaluate Reverse Polish Notation with integer arithmetic.
    Operators: +, -, *, /. Division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division truncates toward zero
                # avoid float overflow by using integer arithmetic
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                # truncation toward zero
                res = abs(a) // abs(b)
                if (a < 0) ^ (b < 0):
